<template><div><header class="page-head"><div><div class="eyebrow">市场行情</div><h1>今日市场联动</h1><p>宽基指数 · 行业热力 · 基金估值环境</p></div></header><section class="index-row market-grid"><div v-for="x in indices" :key="x.code" class="index glass"><span>{{x.name}}</span><b :class="x.change_pct>=0?'up':'down'">{{x.change_pct>=0?'+':''}}{{x.change_pct}}%</b><small>{{x.last_price}}</small></div></section><section class="section"><div class="section-title"><h2>行业热力图</h2></div><div class="heatmap"><div v-for="x in heat" :key="x.industry_name" class="heat glass"><b>{{x.industry_name}}</b><span :class="x.change_pct>=0?'up':'down'">{{x.change_pct>=0?'+':''}}{{x.change_pct}}%</span></div></div></section></div></template><script setup>import{ref,onMounted}from'vue';import{getJSON}from'../api';const indices=ref([]),heat=ref([]);onMounted(async()=>{indices.value=(await getJSON('/market/indices')).data;heat.value=(await getJSON('/market/industries/heatmap')).data})</script>
